import { useState } from "react";
import Sidebar from "../../components/Dashboard/Sidebar";
import Topbar from "../../components/Dashboard/Topbar";
import { useContext } from "react";
import { JobContext } from "../../context/JobContext";
import { useNavigate } from "react-router-dom";
import { useEffect } from "react";
import { getToken } from "../../utils/auth";
import api from "../../utils/api";



import {
  Box,
  Paper,
  Typography,
  Grid,
  TextField,
  MenuItem,
  FormControlLabel,
  Checkbox,
  Button,
} from "@mui/material";

export default function CreateJob() { 
  const initialJobData = {
  title: "",
  company: "",
  location: "",
  employmentType: "",
  experience: "",
  vacancies: "",
  minSalary: "",
  maxSalary: "",
  skills: "",
  description: "",
  requirements: "",
  benefits: "",
  deadline: "",
  workMode: "",
  aiScreening: true,
};
    const [jobData, setJobData] = useState(initialJobData); 
const {
  editingJob,
  setEditingJob,
} = useContext(JobContext);
const navigate = useNavigate(); 
const handleChange = (event) => {
  const { name, value, type, checked } = event.target;

  setJobData((prev) => ({
    ...prev,
    [name]: type === "checkbox" ? checked : value,
  }));
};
useEffect(() => {
  if (editingJob) {
    setJobData(editingJob);
  }
}, [editingJob]);
const handleSubmit = async () => {
  if (!jobData.title.trim()) {
    alert("Job Title is required");
    return;
  }

  if (!jobData.company.trim()) {
    alert("Company Name is required");
    return;
  }

  if (!jobData.location.trim()) {
    alert("Location is required");
    return;
  }

  const token = getToken();

  try {
    if (editingJob) {
      await api.put(
        `/jobs/${editingJob._id}`,
        jobData
      );

      /* await axios.put(
        `http://localhost:5000/api/jobs/${editingJob._id}`,
        jobData,
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );
      */

      alert("Job Updated Successfully!");
      setEditingJob(null);
    } else {
      
      await api.post(
        "/jobs",
        jobData
      );
      /* 
      await axios.post(
        "http://localhost:5000/api/jobs",
        jobData,
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );
      */

      alert("Job Published Successfully!");
    }

    setJobData(initialJobData);
    navigate("/recruiter/jobs");
  } catch (error) {
    console.error(error);
    console.error(error.response);

    alert(error.response?.data?.message || error.message);
  }
};
  return (
    <>
      <Sidebar />
      <Topbar />

      <Box
  sx={{
    ml: "260px",
    mt: "72px",
    p: 4,
    width: "calc(100% - 260px)",
    boxSizing: "border-box",
  }}
>
        <Typography
  variant="h4"
  fontWeight={700}
  mb={4}
>
  {editingJob ? "Update Job" : "Create New Job"}
</Typography>

        <Paper
  sx={{
    p: 4,
    borderRadius: 4,
    maxWidth: 1100,
    mx: "auto",
  }}
>
          <Grid container spacing={3}>
            <Grid item xs={12}>
              <TextField
  fullWidth
  label="Job Title"
  placeholder="Frontend Developer"
  name="title"
  value={jobData.title}
  onChange={handleChange}
/>
            </Grid>

            <Grid item xs={12}>
              <TextField
  fullWidth
  label="Company Name"
  placeholder="TalentFlow Technologies"
  name="company"
  value={jobData.company}
  onChange={handleChange}
/>
            </Grid>

            <Grid item xs={12} sm={6}>
              <TextField
  fullWidth
  label="Location"
  placeholder="Delhi"
  name="location"
  value={jobData.location}
  onChange={handleChange}
/>
            </Grid>

            <Grid item xs={12} sm={6}>
             <TextField
  select
  fullWidth
  label="Employment Type"
  name="employmentType"
  value={jobData.employmentType}
  onChange={handleChange}
>
  <MenuItem value="Full Time">Full Time</MenuItem>
  <MenuItem value="Part Time">Part Time</MenuItem>
  <MenuItem value="Internship">Internship</MenuItem>
  <MenuItem value="Contract">Contract</MenuItem>
</TextField>
            </Grid>

            <Grid item xs={12} md={6}>
              
            </Grid>

     <Grid item xs={12} md={4}>
  <TextField
    fullWidth
    label="Minimum Salary"
    name="minSalary"
    value={jobData.minSalary}
    onChange={handleChange}
  />
</Grid>

<Grid item xs={12} md={4}>
  <TextField
    fullWidth
    label="Maximum Salary"
    name="maxSalary"
    value={jobData.maxSalary}
    onChange={handleChange}
  />
</Grid>

<Grid item xs={12} md={4}>
  <TextField
    fullWidth
    label="Vacancies"
    type="number"
    name="vacancies"
    value={jobData.vacancies}
    onChange={handleChange}
  />
</Grid>

            <Grid item xs={12}>
              <TextField
  fullWidth
  label="Required Skills"
  placeholder="React, Node.js, MongoDB"
  name="skills"
  value={jobData.skills}
  onChange={handleChange}
/>
            </Grid>

            <Grid item xs={12}>
  <TextField
  fullWidth
  multiline
  rows={5}
  label="Job Description"
  name="description"
  value={jobData.description}
  onChange={handleChange}
/>
</Grid>

<Grid item xs={12}>
  <TextField
  fullWidth
  multiline
  rows={4}
  label="Requirements"
  name="requirements"
  value={jobData.requirements}
  onChange={handleChange}
/>
</Grid>

<Grid item xs={12}>
  <TextField
  fullWidth
  multiline
  rows={3}
  label="Benefits"
  name="benefits"
  value={jobData.benefits}
  onChange={handleChange}
/>
</Grid>
            <Grid item xs={12} sm={6}>
  <Typography
    variant="body2"
    sx={{ mb: 1, fontWeight: 600 }}
  >
    Application Deadline
  </Typography>
<TextField
  fullWidth
  type="date"
  
  name="deadline"
  value={jobData.deadline}
  onChange={handleChange}
  InputLabelProps={{
    shrink: true,
  }}
/>
</Grid>

            <Grid item xs={12} sm={6}>
              <TextField
  select
  fullWidth
  label="Work Mode"
  name="workMode"
  value={jobData.workMode}
  onChange={handleChange}
>
  <MenuItem value="Remote">Remote</MenuItem>
  <MenuItem value="Hybrid">Hybrid</MenuItem>
  <MenuItem value="On-site">On-site</MenuItem>
</TextField>
            </Grid>

            <Grid item xs={12}>
              <FormControlLabel
  control={
    <Checkbox
      name="aiScreening"
      checked={jobData.aiScreening}
      onChange={handleChange}
    />
  }
  label="Enable AI Resume Screening"
/>
            </Grid>

            <Grid item xs={12}>
              <Box
                sx={{
                  display: "flex",
                  justifyContent: "flex-end",
                  gap: 2,
                }}
              >
                <Button variant="outlined">
                  Save Draft
                </Button>

                <Button
  variant="contained"
  onClick={handleSubmit}
>
  {editingJob ? "Update Job" : "Publish Job"}
</Button>
              </Box>
            </Grid>
          </Grid>
        </Paper>
      </Box>
    </>
  );
}

import { useEffect, useState } from "react";
import axios from "axios";
import {
  Box,
  Grid,
  Paper,
  Typography,
  Avatar,
  Chip,
  Button,
  TextField,
  IconButton,
  Badge,
  Divider,
} from "@mui/material";

import SearchIcon from "@mui/icons-material/Search";
import NotificationsIcon from "@mui/icons-material/Notifications";
import WorkIcon from "@mui/icons-material/Work";
import GroupIcon from "@mui/icons-material/Group";
import SmartToyIcon from "@mui/icons-material/SmartToy";
import CheckCircleIcon from "@mui/icons-material/CheckCircle";
import ArrowForwardIosIcon from "@mui/icons-material/ArrowForwardIos";

import Sidebar from "../../components/Dashboard/Sidebar";
import Topbar from "../../components/Dashboard/Topbar";
import { getToken, getUser } from "../../utils/auth";

export default function Dashboard() {
  const user = getUser();
  const [applications, setApplications] = useState([]);

  useEffect(() => {
    const fetchData = async () => {
      const token = getToken();

      const res = await axios.get(
        "http://localhost:5000/api/applications",
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      setApplications(res.data.applications.slice(0, 5));
    };

    fetchData();
  }, []);

  const Card = ({ title, value, icon, color }) => (
    <Paper
      sx={{
        p: 3,
        borderRadius: 4,
        boxShadow: 3,
        transition: ".3s",
        "&:hover": {
          transform: "translateY(-5px)",
        },
      }}
    >
      <Avatar sx={{ bgcolor: color, mb: 2 }}>{icon}</Avatar>

      <Typography color="text.secondary">{title}</Typography>

      <Typography variant="h4" fontWeight="bold">
        {value}
      </Typography>
    </Paper>
  );

  return (
    <>
      <Sidebar />
      <Topbar />

      <Box
        sx={{
          ml: "260px",
          mt: "72px",
          p: 4,
          background: "#F4F7FC",
          minHeight: "100vh",
        }}
      >
        {/* Header */}

        <Box
          display="flex"
          justifyContent="space-between"
          alignItems="center"
          mb={4}
        >
          <Box>
            <Typography variant="h4" fontWeight="bold">
              Welcome Back ≡ƒæï
            </Typography>

            <Typography color="text.secondary">
              {user?.name}
            </Typography>
          </Box>

          <Box display="flex" gap={2}>
            <TextField
              size="small"
              placeholder="Search..."
              InputProps={{
                startAdornment: <SearchIcon />,
              }}
            />

            <IconButton>
              <Badge badgeContent={3} color="error">
                <NotificationsIcon />
              </Badge>
            </IconButton>
          </Box>
        </Box>

        {/* KPI */}

        <Grid container spacing={3} mb={4}>
          <Grid item xs={12} md={3}>
            <Card
              title="Open Jobs"
              value={8}
              color="#2563EB"
              icon={<WorkIcon />}
            />
          </Grid>

          <Grid item xs={12} md={3}>
            <Card
              title="Applicants"
              value={applications.length}
              color="#7C3AED"
              icon={<GroupIcon />}
            />
          </Grid>

          <Grid item xs={12} md={3}>
            <Card
              title="AI Match"
              value="92%"
              color="#10B981"
              icon={<SmartToyIcon />}
            />
          </Grid>

          <Grid item xs={12} md={3}>
            <Card
              title="Hired"
              value={3}
              color="#F59E0B"
              icon={<CheckCircleIcon />}
            />
          </Grid>
        </Grid>

        {/* Main */}

        <Grid container spacing={3}>
          <Grid item xs={12} lg={8}>
            <Paper sx={{ p: 3, borderRadius: 4 }}>
              <Typography variant="h6" fontWeight="bold" mb={2}>
                Latest Applicants
              </Typography>

              {applications.map((app) => (
                <Box key={app._id}>
                  <Box
                    display="flex"
                    justifyContent="space-between"
                    alignItems="center"
                    py={2}
                  >
                    <Box display="flex" gap={2} alignItems="center">
                      <Avatar>
                        {app.applicant?.name?.charAt(0)}
                      </Avatar>

                      <Box>
                        <Typography fontWeight="bold">
                          {app.applicant?.name}
                        </Typography>

                        <Typography
                          variant="body2"
                          color="text.secondary"
                        >
                          {app.job?.title}
                        </Typography>
                      </Box>
                    </Box>

                    <Box display="flex" gap={2} alignItems="center">
                      <Chip
                        label={app.status}
                        color={
                          app.status === "Accepted"
                            ? "success"
                            : app.status === "Rejected"
                            ? "error"
                            : "warning"
                        }
                      />

                      <ArrowForwardIosIcon fontSize="small" />
                    </Box>
                  </Box>

                  <Divider />
                </Box>
              ))}

              <Box textAlign="center" mt={3}>
                <Button variant="contained">
                  View All Applicants
                </Button>
              </Box>
            </Paper>
          </Grid>

          <Grid item xs={12} lg={4}>
            <Paper sx={{ p: 3, borderRadius: 4 }}>
              <Typography variant="h6" fontWeight="bold" mb={3}>
                Quick Actions
              </Typography>

              <Button
                fullWidth
                variant="contained"
                sx={{ mb: 2 }}
              >
                + Post Job
              </Button>

              <Button
                fullWidth
                variant="outlined"
                sx={{ mb: 2 }}
              >
                View Applicants
              </Button>

              <Button
                fullWidth
                variant="outlined"
              >
                AI Resume Screening
              </Button>
            </Paper>
          </Grid>
        </Grid>
      </Box>
    </>
  );
}

import { useState, useEffect } from "react";
import Sidebar from "../../components/Dashboard/Sidebar";
import Topbar from "../../components/Dashboard/Topbar";
import JobCard from "../../components/Jobs/JobCard";
import { Button, Box } from "@mui/material";
import { Link } from "react-router-dom";
import axios from "axios";
import { getToken } from "../../utils/auth";
export default function Jobs() {
  const [jobs, setJobs] = useState([]);

const fetchJobs = async () => {
  try {
    const token = getToken();

    const res = await axios.get(
      "http://localhost:5000/api/jobs",
      {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      }
    );
    console.log(res.data);

    setJobs(res.data.data);
  } catch (error) {
    console.error(error);
  }
};

useEffect(() => {
  fetchJobs();
}, []);
  return (
    <>
      <Sidebar />
      <Topbar />

      <div
        style={{
          marginLeft: "260px",
          marginTop: "72px",
          padding: "30px",
        }}
      >
       <>
  <Box
    sx={{
      display: "flex",
      justifyContent: "space-between",
      alignItems: "center",
      mb: 4,
    }}
  >
    <h1>Jobs</h1>

   <Button
  component={Link}
  to="/recruiter/jobs/create"
  variant="contained"
>
  + Create Job
</Button>
  </Box>

  {jobs.length === 0 ? (
  <Box
    sx={{
      textAlign: "center",
      mt: 8,
      color: "text.secondary",
    }}
  >
    <h2>No Jobs Posted Yet</h2>
    <p>Click "Create Job" to publish your first job.</p>
  </Box>
) : (
  jobs.map((job) => (
  <Box key={job._id} sx={{ mb: 3 }}>
    <JobCard
  job={job}
  refreshJobs={fetchJobs}
/>
  </Box>
))
)}
</>
      </div>
    </>
  );
}
